2	// Labels are stored data: an open item wears whatever the engine that filed it
3	// wrote, and a member converges on its own schedule. So every reader decodes, and
4	// what these tests pin is that ONE pass maps every spelling ever written straight
5	// to today's — plus the two places that would silently strand a member if they
6	// disagreed: the ensure-list (a label that does not exist 422s the write that
7	// applies it) and the executor workflow's literal event trigger.
8	import { test } from 'node:test';
9	import assert from 'node:assert/strict';
10	import { readFileSync } from 'node:fs';
11	import {
12	  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN,
13	  TASK_DONE, TASK_OBSOLETE, OUTCOME_DONE, OUTCOME_OBSOLETE, OUTCOME_DELIVERED,
14	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
15	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
16	  STATUS_NEEDS_HUMAN_ACTION, STATUS_NEEDS_HUMAN_APPROVAL, STATUS_NEEDS_HUMAN_DECISION,
17	  STATUS_NEEDS_HUMAN_FAILURE, STATUS_DONE, STATUS_REJECTED,
18	  STATUS_LABELS, ORIGIN_LABELS, ORIGIN_PLANNED, ORIGIN_AD_HOC, ORIGIN_GITHUB, ORIGIN_SCHEDULE,
19	  QUEUE_LABELS, statusOf, statusesOn, isStatus, isParked, parkKindOf, originOf,
20	  spellingsOf, isBlockingPark, outcomeOf,
21	} from '../../../engine/scheduler/queue/work-item.mjs';
22	import { swapStatus, clearStatus } from '../../../engine/scheduler/queue/apply-status.mjs';
23	
24	const item = (...labels) => ({ number: 1, title: '[claudinite-work] basics/task-janitor', state: 'open', labels });
25	
26	// DESIGN §4's legacy table, in full — the left column is every spelling any fielded
27	// engine has written, the right is what a reader must see today.
28	test('every legacy spelling decodes straight to its canonical status', () => {
29	  for (const [legacy, canonical] of [
